/**
* @param {params} params
* @param {api} params.api
* @param {any} params.event
*/
function evaluateEvent({api, event}) {
	var res = api.state.updatedConfig;
	res[api?.item?.value?.providerId] = event.payload?.value;

	return {
		propName: "updatedConfig",
		value: res
	};
}
